package com.nanolaba.nrg;

import com.nanolaba.nrg.core.json.MinimalJsonParser;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.Map;
import java.util.function.Function;

import static org.junit.jupiter.api.Assertions.*;

/**
 * {@code --claude-hook}: the PreToolUse guard against edits of generated files and the
 * PostToolUse validate-and-regenerate step, driven by hook JSON on stdin.
 */
public class ClaudeHookTest extends DefaultNRGTest {

    @TempDir
    Path tempDir;

    private Path write(String name, String body) throws IOException {
        Path p = tempDir.resolve(name);
        Files.createDirectories(p.getParent());
        Files.write(p, body.getBytes(StandardCharsets.UTF_8));
        return p;
    }

    private int hook(String mode, Path file) {
        return hook(mode, file, tempDir, name -> null);
    }

    private int hook(String mode, Path file, Path cwd, Function<String, String> env) {
        String json = "{\"cwd\": " + RunReport.str(cwd.toString()) + ", \"tool_name\": \"Edit\", "
                + "\"tool_input\": {\"file_path\": " + RunReport.str(file.toString()) + "}}";
        return new ClaudeHook(StandardCharsets.UTF_8, Collections.emptyList(), env)
                .run(mode, new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));
    }

    @SuppressWarnings("unchecked")
    private static String additionalContext(String out) {
        String json = out.substring(out.lastIndexOf("{\"hookSpecificOutput\""));
        Map<String, Object> specific = (Map<String, Object>) ((Map<String, Object>) MinimalJsonParser.parse(json)).get("hookSpecificOutput");
        assertEquals("PostToolUse", specific.get("hookEventName"));
        return (String) specific.get("additionalContext");
    }

    private Path project() throws IOException {
        write("docs/part.src.md", "Part<!--en-->\nЧасть<!--ru-->\n");
        Path src = write("README.src.md", "<!--@nrg.languages=en,ru-->\n${widget:import(path='docs/part.src.md')}\n");
        assertEquals(NRG.EXIT_OK, NRG.run("-f", src.toString()));
        getOutAndClear();
        getErrAndClear();
        return src;
    }

    @Test
    public void testPreEditBlocksGeneratedFilesWithTheTemplateName() throws IOException {
        project();

        assertEquals(2, hook("pre-edit", tempDir.resolve("README.ru.md")));
        String err = getErrAndClear();
        assertTrue(err.contains("README.ru.md is generated by NRG from") && err.contains("README.src.md"), err);
        assertTrue(err.contains("nrg --locate"), err);
    }

    @Test
    public void testPreEditAllowsTemplatesAndOtherFiles() throws IOException {
        project();

        assertEquals(NRG.EXIT_OK, hook("pre-edit", tempDir.resolve("README.src.md")));
        assertEquals(NRG.EXIT_OK, hook("pre-edit", tempDir.resolve("docs/part.src.md")));
        assertEquals(NRG.EXIT_OK, hook("pre-edit", tempDir.resolve("src/Main.java")));
        assertEquals("", getErrAndClear().trim());
    }

    @Test
    public void testPostEditRegeneratesAndReportsContext() throws IOException {
        project();
        Path fragment = write("docs/part.src.md", "Changed<!--en-->\nИзменено<!--ru-->\n");
        getOutAndClear();

        assertEquals(NRG.EXIT_OK, hook("post-edit", fragment));
        String context = additionalContext(getOutAndClear().trim());
        assertTrue(context.startsWith("NRG regenerated ") && context.contains("README.ru.md"), context);
        assertTrue(context.endsWith("from the templates; commit them together with the template."),
                "no warnings, no warnings section: " + context);
        assertTrue(new String(Files.readAllBytes(tempDir.resolve("README.ru.md")), StandardCharsets.UTF_8).contains("Изменено"));
    }

    @Test
    public void testPostEditPassesValidationWarningsOn() throws IOException {
        project();
        Path fragment = write("docs/part.src.md", "Changed ${HOME}<!--en-->\nИзменено ${HOME}<!--ru-->\n");
        getOutAndClear();

        assertEquals(NRG.EXIT_OK, hook("post-edit", fragment));
        String context = additionalContext(getOutAndClear().trim());
        assertTrue(context.contains("; commit them together with the template. Warnings from --validate: WARNING: part.src.md:1: "),
                context);
    }

    @Test
    public void testPostEditReportsAFailedRegeneration() throws IOException {
        project();
        Path src = write("README.src.md", "<!--@nrg.fileNamePattern=../../outside/<base>.md-->\nx\n");

        assertEquals(2, hook("post-edit", src));
        String err = getErrAndClear();
        assertTrue(err.startsWith("NRG: regeneration failed:"), err);
        assertTrue(err.contains("outside the project root"), "the output of the failed run is passed on: " + err);
    }

    @Test
    public void testUnknownModeIsAUsageError() throws IOException {
        project();

        assertEquals(NRG.EXIT_USAGE, hook("mid-edit", tempDir.resolve("README.md")));
        assertTrue(getErrAndClear().contains("--claude-hook expects pre-edit or post-edit, got 'mid-edit'"));
    }

    @Test
    public void testProjectDirectoryComesFromClaudeProjectDirBeforeCwd() throws IOException {
        project();
        Path elsewhere = Files.createDirectories(tempDir.resolve("elsewhere"));
        Path readme = tempDir.resolve("README.ru.md");

        assertEquals(2, hook("pre-edit", readme, elsewhere,
                name -> "CLAUDE_PROJECT_DIR".equals(name) ? tempDir.toString() : null));
        assertEquals(2, hook("pre-edit", readme, tempDir, name -> ""), "an empty CLAUDE_PROJECT_DIR is not set");
        assertEquals(NRG.EXIT_OK, hook("pre-edit", readme, elsewhere, name -> null),
                "without CLAUDE_PROJECT_DIR the cwd of the event is the project");
    }

    @Test
    public void testPostEditFeedsValidationErrorsBack() throws IOException {
        project();
        Path fragment = write("docs/part.src.md", "${widget:tocc}\n");

        assertEquals(2, hook("post-edit", fragment));
        String err = getErrAndClear();
        assertTrue(err.startsWith("NRG: the edit leaves a template invalid; fix it before going on:"), err);
        assertTrue(err.contains("unknown widget 'tocc'"), err);
        assertFalse(new String(Files.readAllBytes(tempDir.resolve("README.md")), StandardCharsets.UTF_8).contains("tocc"),
                "nothing is regenerated from an invalid template");
    }

    @Test
    public void testUnrelatedEditsAndBadInputAreIgnored() throws IOException {
        project();

        assertEquals(NRG.EXIT_OK, hook("post-edit", tempDir.resolve("notes.txt")));
        assertEquals(NRG.EXIT_OK, new ClaudeHook(StandardCharsets.UTF_8, Collections.emptyList(), name -> null)
                .run("pre-edit", new ByteArrayInputStream("not json".getBytes(StandardCharsets.UTF_8))));
        assertEquals("", getErrAndClear().trim());
    }

    @Test
    public void testHookTurnsNanologAgentModeOffUnlessSetExplicitly() {
        String saved = System.getProperty("nanolog.agent");
        try {
            System.clearProperty("nanolog.agent");
            NRG.quietAgentModeForHook(new String[]{"-f", "README.src.md"}, name -> null);
            assertNull(System.getProperty("nanolog.agent"), "only the hook is quieted");

            NRG.quietAgentModeForHook(new String[]{"--claude-hook", "pre-edit"}, name -> null);
            assertEquals("off", System.getProperty("nanolog.agent"));

            System.clearProperty("nanolog.agent");
            NRG.quietAgentModeForHook(new String[]{"--claude-hook=post-edit"}, name -> null);
            assertEquals("off", System.getProperty("nanolog.agent"));

            System.clearProperty("nanolog.agent");
            NRG.quietAgentModeForHook(new String[]{"--claude-hook", "pre-edit"},
                    name -> "NANOLOG_AGENT".equals(name) ? "on" : null);
            assertNull(System.getProperty("nanolog.agent"), "NANOLOG_AGENT set by the user wins");

            System.setProperty("nanolog.agent", "on");
            NRG.quietAgentModeForHook(new String[]{"--claude-hook", "pre-edit"}, name -> null);
            assertEquals("on", System.getProperty("nanolog.agent"), "-Dnanolog.agent set by the user wins");
        } finally {
            if (saved == null) {
                System.clearProperty("nanolog.agent");
            } else {
                System.setProperty("nanolog.agent", saved);
            }
        }
    }

    @Test
    public void testHelpSyntaxPrintsTheBundledCard() {
        assertEquals(NRG.EXIT_OK, NRG.run("--help", "syntax"));
        assertTrue(getOutAndClear().contains("# NRG syntax card"));
    }
}
